//! Progress numeric metadata uses actual native/inert attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><label id=label for=progress>Work</label><progress id=progress value=2 max=10>Fallback</progress><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://progress-numeric.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn progress_numeric_canonical_descriptors_and_initial_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('progress'),P=HTMLProgressElement.prototype;if(!(x instanceof HTMLProgressElement))throw 'progress interface';for(var key of ['value','max','position']){var a=Object.getOwnPropertyDescriptor(P,key);if(!a||typeof a.get!=='function'||!a.enumerable||!a.configurable||a.get.length!==0||a.get.name!=='get '+key||Object.hasOwn(x,key))throw 'canonical numeric getter';if(key==='position'){if(a.set!==undefined)throw 'readonly position';}else{if(typeof a.set!=='function'||a.set.length!==1||a.set.name!=='set '+key)throw 'canonical numeric setter';}}if(x.value!==2||x.max!==10||x.position!==0.2||x.labels[0]!==document.getElementById('label'))throw 'actual progress initial values';");}
#[test]
fn progress_numeric_live_public_attributes_determine_clamping_and_indeterminate_state(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('progress');if(x.value!==2||x.max!==10||x.position!==0.2)throw 'initial progress numbers';x.setAttribute('value','25junk');if(x.value!==10||x.position!==1||x.getAttribute('value')!=='25junk')throw 'native parsed prefix and current clamp';x.setAttribute('max','40');if(x.value!==25||x.max!==40||x.position!==0.625)throw 'current actual maximum';x.removeAttribute('value');if(x.value!==0||x.max!==40||x.position!==-1)throw 'indeterminate without value';");}
#[test]
fn progress_numeric_inert_setters_convert_once_keep_raw_value_and_ignore_nonpositive_max(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','progress');if(x.value!==0||x.max!==1||x.position!==-1)throw 'inert numeric defaults';x.max=4;x.value=6;if(x.max!==4||x.value!==4||x.position!==1||x.getAttribute('value')!=='6')throw 'raw value and computed clamp';x.max=-1;if(x.max!==4||x.getAttribute('max')!=='4')throw 'nonpositive maximum ignored';x.value=-2;if(x.value!==0||x.position!==0||x.getAttribute('value')!=='-2')throw 'negative raw value';var calls=0;x.value={valueOf:function(){calls++;x.max=8;return 6;}};if(calls!==1||x.value!==6||x.max!==8||x.position!==0.75)throw 'live number conversion';var caught=false;try{x.value=Infinity;}catch(e){caught=e instanceof TypeError;}if(!caught||x.getAttribute('value')!=='6')throw 'finite double conversion';");}

#[test]
fn progress_numeric_finite_conversion_ignored_max_and_actual_observer_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('progress'),value=x.getAttributeNode('value'),max=x.getAttributeNode('max'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var n of [0,-0,-1])x.max=n;if(watch.takeRecords().length||x.max!==10||max.value!=='10')throw 'nonpositive max has no mutation';for(var key of ['value','max']){for(var n of [NaN,Infinity,-Infinity,undefined,Symbol('n'),BigInt(1)]){var caught=false;try{x[key]=n;}catch(e){caught=e instanceof TypeError;}if(!caught||value.value!=='2'||max.value!=='10'||watch.takeRecords().length)throw 'finite double refusal';}}var marker={},caught;try{x.value={valueOf:function(){x.max=20;throw marker;}};}catch(e){caught=e;}var records=watch.takeRecords();if(caught!==marker||x.value!==2||x.max!==20||records.length!==1||records[0].attributeName!=='max'||records[0].oldValue!=='10')throw 'abrupt conversion keeps author effects';x.value=25;records=watch.takeRecords();if(x.value!==20||x.position!==1||value.value!=='25'||records.length!==1||records[0].oldValue!=='2'||x.getAttributeNode('value')!==value)throw 'actual numeric setter record';");}
#[test]
fn progress_numeric_native_and_inert_attribute_grammar_aliases_and_namespace(){for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','progress');x.setAttribute('max','10');x.setAttribute('value','2');"}else{"var x=document.getElementById('progress');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('value'),b=x.getAttributeNode('max');a.value='  +1.5e1suffix';if(x.value!==10||x.position!==1)throw 'prefix exceeds max';b.nodeValue='2.5e1';if(x.max!==25||x.value!==15||x.position!==0.6)throw 'attached maximum';a.textContent='3\ud800tail';if(x.value!==3||a.value!=='3\ud800tail')throw 'raw exact numeric prefix';a.value='\ud8003';if(x.value!==0||x.position!==0)throw 'invalid raw leading unit';x.setAttributeNS('urn:foreign','value','99');x.setAttributeNS(null,'VALUE','88');if(x.value!==0||x.getAttributeNodeNS(null,'value')!==a)throw 'exact namespace local name';x.setAttributeNS(null,'value','-.5');if(x.value!==0||x.position!==0)throw 'negative numeric floor';a.value='1e309';b.value='1e309';if(x.value!==0||x.max!==1||x.position!==0)throw 'overflow defaults';x.removeAttributeNS(null,'value');if(x.value!==0||x.position!==-1||x.max!==1)throw 'presence only determinate';"#);}}
#[test]
fn progress_numeric_descriptors_brands_readonly_author_overrides_and_saved_constructor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('progress'),C=HTMLProgressElement,P=C.prototype,calls=0;for(var key of ['value','max','position']){var a=Object.getOwnPropertyDescriptor(P,key),expected=key==='value'?2:key==='max'?10:0.2;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','progress'),new Document().createElementNS('http://www.w3.org/1999/xhtml','PROGRESS')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine numeric getter brand';if(a.set){caught=false;try{a.set.call(bad,{valueOf:function(){calls++;return 1;}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand precedes number conversion';}}Object.defineProperty(x,key,{value:'author',writable:true,configurable:true});if(x[key]!=='author'||a.get.call(x)!==expected)throw 'native numeric authority';delete x[key];if(x[key]!==expected)throw 'numeric getter restored';}x.position={valueOf:function(){calls++;return 1;}};var caught=false;try{(function(){'use strict';x.position=1;})();}catch(e){caught=e instanceof TypeError;}if(!caught||calls||x.position!==0.2)throw 'readonly position';delete window.HTMLProgressElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved numeric interface';");}
#[test]
fn progress_numeric_inert_clone_adoption_keeps_actual_values_and_independent_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','p:progress');x.max=20;x.value=5;var clone=x.cloneNode(false),a=clone.getAttributeNode('value'),target=new Document();target.adoptNode(x);if(x.ownerDocument!==target||x.value!==5||x.max!==20||x.position!==0.25||clone.value!==5||clone.position!==0.25||a===x.getAttributeNode('value'))throw 'actual inert clone adoption';x.value=15;if(x.position!==0.75||clone.position!==0.25||a.value!=='5')throw 'independent cloned attribute authority';");}
#[test]
fn progress_numeric_saved_child_origin_precedes_number_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('progress'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLProgressElement,a=Object.getOwnPropertyDescriptor(C.prototype,'value'),calls=0;if(C===HTMLProgressElement||a.get.call(x)!==2)throw 'captured numeric getter';");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-progress.test/",&crate::navigation::Location::home()).unwrap());for source in ["a.get.call(x);","a.set.call(x,{valueOf:function(){calls++;return 3;}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://progress-numeric.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,3);if(a.get.call(x)!==3||x.position!==0.3)throw 'numeric origin recovery';");}
#[test]
fn progress_numeric_read_budget_has_no_copy_string_or_new_storage_requirement(){for method in [script_progress_numeric::VALUE_GET,script_progress_numeric::MAX_GET,script_progress_numeric::POSITION_GET]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("progress")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.copy_work=0;p.state.limits.host.string_bytes=0;p.state.retained_limit=p.state.retained;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.progress_numeric_get(node_handle(n),method);if mode==2{let expected=if method==script_progress_numeric::VALUE_GET{2.0}else if method==script_progress_numeric::MAX_GET{10.0}else{0.2};assert!(matches!(result.unwrap(),Value::Number(n)if n==expected));}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=256*1024*1024;p.state.limits.host.string_bytes=1024;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.progress_numeric_get(node_handle(n),method).is_ok());}}}
#[test]
fn progress_numeric_writer_refusal_preserves_native_and_inert_records_and_recovers(){for inert in [false,true]{for(source,key)in[("x.value=12.5;","value"),("x.max=12.5;","max"),("x.setAttribute('value','12.5');","value"),("attr.value='12.5';","value"),("attr.nodeValue='12.5';","value"),("attr.textContent='12.5';","value")]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','progress');x.setAttribute('value','2');x.setAttribute('max','10');"}else{"var x=document.getElementById('progress');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('value'),max=x.getAttributeNode('max'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='2'||max.value!=='10'||watch.takeRecords().length)throw 'atomic numeric writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,&format!("var records=watch.takeRecords();if(x.getAttribute('{key}')!=='12.5'||records.length!==1||records[0].attributeName!=='{key}'||x.getAttributeNode('value')!==attr||x.getAttributeNode('max')!==max)throw 'fresh numeric writer recovery';"));}}}}
